#!/bin/bash # organize_by_date.sh TARGET_DIR="organized_by_date"
for file in *; do if [ -f "$file" ]; then # Get file modification year and month year=$(date -r "$file" +%Y) month=$(date -r "$file" +%m)
# Create directory structure mkdir -p "$TARGET_DIR/$year/$month"
# Move file preserving original name mv "$file" "$TARGET_DIR/$year/$month/" fi done
echo "Organization complete. Files moved to $TARGET_DIR"

#!/usr/bin/env python3 import os import re from pathlib import Path
def extract_info_from_content(file_path): """Extract key information from file content""" # This would use OCR or text extraction # For demo, assume we have content extraction function content = extract_text(file_path)
# Look for patterns title_match = re.search(r'Title:\s*(.+?)(?:\n|$)', content, re.IGNORECASE) author_match = re.search(r'Author:\s*(.+?)(?:\n|$)', content, re.IGNORECASE) date_match = re.search(r'Date:\s*(\d{1,2}/\d{1,2}/\d{4})', content)
return { 'title': title_match.group(1).strip() if title_match else '', 'author': author_match.group(1).strip() if author_match else '', 'date': date_match.group(1) if date_match else '' }
def rename_file_smart(file_path): """Rename file based on extracted content""" info = extract_info_from_content(file_path)
if info['title'] and info['author']: # Create new name title_clean = re.sub(r'[^\w\-_\. ]', '', info['title']).replace(' ', '_') author_clean = re.sub(r'[^\w\-_\. ]', '', info['author']).replace(' ', '_') new_name = f"{author_clean}_{title_clean}.pdf"
new_path = file_path.parent / new_name file_path.rename(new_path) print(f"Renamed: {file_path.name} -> {new_name}")
# Process all PDFs in current directory for pdf_file in Path('.').glob('*.pdf'): rename_file_smart(pdf_file)

#!/bin/bash # organize_images.sh
TARGET_DIR="organized_images"
for file in *; do if [ -f "$file" ]; then # Get creation date from EXIF or file system date_info=$(exiftool -s3 -DateTimeOriginal "$file" 2>/dev/null || exiftool -s3 -CreateDate "$file" 2>/dev/null || date -r "$file" +%Y-%m-%d)
if [ -n "$date_info" ]; then # Extract year and month year=$(echo "$date_info" | cut -d: -f1 | cut -d' ' -f1) month=$(echo "$date_info" | cut -d: -f2 | cut -d' ' -f1)
# Create directory structure mkdir -p "$TARGET_DIR/$year/$month"
# Move file mv "$file" "$TARGET_DIR/$year/$month/" echo "Moved $file to $year/$month/" else # No date info, put in undated folder mkdir -p "$TARGET_DIR/undated" mv "$file" "$TARGET_DIR/undated/" fi fi done
